SELECT run_kind, COUNT(*) AS rows_, MIN(analysis_date) AS first_date, MAX(analysis_date) AS last_date, COUNT(*) FILTER (WHERE level_basis IS NOT NULL) AS with_level_basis FROM premarket_analysis WHERE ticker IN ('SPY','QQQ','IWM') GROUP BY 1 ORDER BY 1;
SELECT d.analysis_date, t.ticker, p.run_kind, p.level_basis->>'status' AS brief_levels_status, p.level_basis->>'last_bar_date' AS last_bar_date, p.calls_trigger_price, p.puts_trigger_price, p.signal_status, p.analysis_ts, (SELECT string_agg(DISTINCT concat(r.run_kind, ':', r.report->>'regime'), ',') FROM insight_reports r WHERE r.ticker = t.ticker AND (r.as_of AT TIME ZONE 'America/New_York')::date = d.analysis_date) AS insight_kind_regimes FROM (VALUES (DATE '2025-04-21'), (DATE '2025-05-27'), (DATE '2025-06-20'), (DATE '2025-07-07'), (DATE '2025-09-02'), (DATE '2025-11-28'), (DATE '2025-12-26'), (DATE '2026-01-02'), (DATE '2026-01-20'), (DATE '2026-02-17'), (DATE '2026-04-06'), (DATE '2026-05-26'), (DATE '2026-06-22'), (DATE '2026-07-06'), (DATE '2026-09-08')) AS d(analysis_date) CROSS JOIN (VALUES ('SPY'), ('QQQ'), ('IWM')) AS t(ticker) LEFT JOIN premarket_analysis p ON p.ticker = t.ticker AND p.analysis_date = d.analysis_date ORDER BY d.analysis_date, t.ticker, p.run_kind;
SELECT date_trunc('month', analysis_date)::date AS month, run_kind, COUNT(*) AS rows_, COUNT(DISTINCT analysis_date) AS dates, COUNT(*) FILTER (WHERE calls_trigger_price IS NOT NULL OR puts_trigger_price IS NOT NULL) AS with_trigger, COUNT(*) FILTER (WHERE level_basis IS NOT NULL) AS with_level_basis FROM premarket_analysis WHERE ticker IN ('SPY','QQQ','IWM') AND analysis_date >= DATE '2025-03-01' GROUP BY 1, 2 ORDER BY 1, 2;
SELECT (as_of AT TIME ZONE 'America/New_York')::date AS session_et, ticker, COUNT(*) AS history_rows, string_agg(DISTINCT run_kind, ',') AS kinds FROM insight_reports_history WHERE ticker IN ('SPY','QQQ','IWM') AND (as_of AT TIME ZONE 'America/New_York')::date IN (DATE '2025-11-28', DATE '2025-12-26', DATE '2026-01-02', DATE '2026-01-20', DATE '2026-02-17', DATE '2026-04-06', DATE '2026-05-26', DATE '2026-06-22', DATE '2026-07-06', DATE '2026-09-08') GROUP BY 1, 2 ORDER BY 1, 2;
